//! The 32-bit rv32im build of esm-core, executed instruction by instruction in the emulator, must reproduce the golden
//! vectors (generated by the Python reference) bit for bit -- the same vectors the 64-bit host build passes.
use std::collections::BTreeMap;
use zkvm_sim::*;

fn golden() -> Vec<Vec<String>> {
    let p = concat!(env!("CARGO_MANIFEST_DIR"), "/../spec/vectors/golden.txt");
    std::fs::read_to_string(p).unwrap().lines().filter(|l| !l.is_empty() && !l.starts_with('#')).map(|l| l.split_whitespace().map(String::from).collect()).collect()
}
fn bits(s: &str) -> Vec<u8> {
    if s == "-" { vec![] } else { s.bytes().map(|b| b - b'0').collect() }
}
struct Table {
    progs: Vec<Vec<u8>>,
    idx: BTreeMap<Vec<u8>, u32>,
}
impl Table {
    fn new() -> Table { Table { progs: vec![], idx: BTreeMap::new() } }
    fn id(&mut self, b: Vec<u8>) -> u32 {
        if let Some(&i) = self.idx.get(&b) { return i; }
        let i = self.progs.len() as u32;
        self.progs.push(b.clone());
        self.idx.insert(b, i);
        i
    }
}
const BUDGET: u64 = 40_000_000_000;

#[test]
fn run_vectors_on_rv32im_match_golden() {
    let elf = load_guest();
    let g = golden();
    let (mut t, mut cases, mut want) = (Table::new(), vec![], vec![]);
    for l in g.iter().filter(|l| l[0] == "RUN" || l[0] == "RUNB") {
        let (width, delta, j): (u32, u32, u64) = (l[1].parse().unwrap(), l[2].parse().unwrap(), l[3].parse().unwrap());
        let (prog, args, tail): (Vec<u8>, Vec<Vec<u8>>, usize) = if l[0] == "RUN" {
            let na: usize = l[5].parse().unwrap();
            (bits(&l[4]), (0..na).map(|i| bits(&l[6 + i])).collect(), 6 + na)
        } else {
            (bits(&l[4]), vec![], 5)
        };
        let (v, s, ok): (u64, u32, u32) = (l[tail].parse().unwrap(), l[tail + 1].parse().unwrap(), l[tail + 2].parse().unwrap());
        let pi = t.id(prog);
        let ai: Vec<u32> = args.into_iter().map(|a| t.id(a)).collect();
        cases.push(Case1 { prog: pi, args: ai, j, width, delta });
        want.push((ok, s, v));
    }
    assert!(cases.len() > 1900);
    let run = run_mode1(&elf, &t.progs, &cases, BUDGET).unwrap();
    for (i, (r, w)) in run.results.iter().zip(&want).enumerate() {
        assert_eq!((r.ok, r.steps, r.value), *w, "case {i}: {:?}", g.iter().filter(|l| l[0].starts_with("RUN")).nth(i).unwrap());
    }
    eprintln!("RUN vectors: {} cases, {} instructions retired, heap high-water {} KiB", cases.len(), run.total_instret, run.heap_high_water / 1024);
    assert_eq!(run.guest_total_instret <= run.total_instret, true);
}

#[test]
fn benchmarks_1_to_3_on_rv32im_match_reference_records() {
    let elf = load_guest();
    let g = golden();
    let prog = |n: &str| bits(&g.iter().find(|l| l[0] == "PROG" && l[1] == n).unwrap()[2]);
    let col = |k: &str, n: &str| -> Vec<u64> { g.iter().find(|l| l[0] == k && l[1] == n).unwrap()[2..].iter().map(|x| x.parse().unwrap()).collect() };
    for (b, w, args) in [("b1", "w1", vec![]), ("b2", "w2", vec!["vs"]), ("b3", "w3", vec!["vs"])] {
        let mut t = Table::new();
        let pi = t.id(prog(w));
        let ai: Vec<u32> = args.iter().map(|a| t.id(prog(a))).collect();
        let cases: Vec<Case1> = (0..1024u64).map(|j| Case1 { prog: pi, args: ai.clone(), j, width: 16, delta: 1 << 20 }).collect();
        let run = run_mode1(&elf, &t.progs, &cases, BUDGET).unwrap();
        let (out, steps) = (col("OUT", b), col("STEPS", b));
        for j in 0..1024 {
            let r = &run.results[j];
            assert_eq!((r.ok, r.value, r.steps as u64), (1, out[j], steps[j]), "{b} record {j}");
        }
    }
}

#[test]
fn t6_on_rv32im_matches_golden() {
    let elf = load_guest();
    let g = golden();
    let named: BTreeMap<String, Vec<u8>> = g.iter().filter(|l| l[0] == "PROG").map(|l| (l[1].clone(), bits(&l[2]))).collect();
    let (mut t, mut cases, mut want) = (Table::new(), vec![], vec![]);
    for l in g.iter().filter(|l| l[0] == "T6" || l[0] == "T6F") {
        let get = |s: &str| if l[0] == "T6" { named[s].clone() } else { bits(s) };
        let (a, b, c) = (t.id(get(&l[1])), t.id(get(&l[2])), t.id(get(&l[3])));
        cases.push((a, b, c, l[4].parse::<u32>().unwrap()));
        let eq = match l[5].as_str() { "False" => 0, "True" => 1, _ => 2 };
        let st = match l[11].as_str() { "equal" => 0, "not-equal" => 1, "fuel-exhausted" => 2, _ => 3 };
        let n = |i: usize| l[i].parse::<u32>().unwrap();
        want.push((eq, st, n(7), n(8), n(9), n(10)));
    }
    assert!(cases.len() >= 718);
    let run = run_mode2(&elf, &t.progs, &cases, BUDGET).unwrap();
    for (i, (r, w)) in run.results.iter().zip(&want).enumerate() {
        assert_eq!((r.eq, r.status, r.kam, r.beta, r.nodes, r.work), *w, "case {i}");
    }
    eprintln!("T6 vectors: {} cases, {} instructions retired, heap high-water {} KiB", cases.len(), run.total_instret, run.heap_high_water / 1024);
}
